const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { watchProgress } = require('../progress.cjs');
test('stop removes only this subscription', () => {
  const emitter = new EventEmitter();
  const log = [];
  emitter.on('progress', value => log.push('outside:' + value));
  const stopA = watchProgress(emitter, value => log.push('A:' + value));
  const stopB = watchProgress(emitter, value => log.push('B:' + value));
  emitter.emit('progress', 1);
  stopA(); stopA();
  assert.equal(emitter.listenerCount('progress'), 2);
  emitter.emit('progress', 2);
  stopB(); emitter.emit('progress', 3);
  assert.deepEqual(log, ['outside:1','A:1','B:1','outside:2','B:2','outside:3']);
});
test('same callback can be owned by multiple subscriptions', () => {
  const emitter = new EventEmitter();
  const log = [], listener = (...args) => log.push(args);
  emitter.on('progress', listener);
  const stop = watchProgress(emitter, listener);
  stop();
  emitter.emit('progress', 'job2', 80);
  assert.deepEqual(log, [['job2',80]]);
});

test('active subscription forwards every argument with its identity', () => {
  const emitter = new EventEmitter();
  const item = {id:'job7'}, flags = ['resumed'], calls = [];
  const stop = watchProgress(emitter, (...args) => calls.push(args));
  emitter.emit('progress', item, 60, flags, undefined);
  emitter.emit('progress');
  assert.equal(calls[0].length, 4);
  assert.strictEqual(calls[0][0], item);
  assert.equal(calls[0][1], 60);
  assert.strictEqual(calls[0][2], flags);
  assert.equal(calls[0][3], undefined);
  assert.deepEqual(calls[1], []);
  stop();
  emitter.emit('progress', 'stopped');
  assert.equal(calls.length, 2);
});

